/**
 * Python boundary tests.
 *
 * The JS path probes values through the module system and emits assertions in the
 * project's framework. Python needs the same shape with different syntax:
 *
 *   - the import is `from pkg.mod import fn`, resolved by putting the project root
 *     on sys.path (a generated file cannot assume it is run from the root)
 *   - the assertion is `assert actual == expected`, with a tolerance for floats
 *   - pytest discovers `test_*.py`, so the file name must follow that convention
 *
 * Probing works the same way conceptually: call the function at the threshold and
 * its neighbours, read the real return values, pin them.
 */

/**
 * Emit a Python file that pins the observed values at the boundary.
 *
 * @param {object} opts
 * @param {string} opts.importPath   dotted module path, e.g. `src.limits`
 * @param {string} opts.sourceName
 * @param {{ fn: string, op: string, constantName: string, values: {at:number,below:number,above:number}, observed: any[] }[]} opts.cases
 */
/** A name safe to put in a Python identifier (functional test name). */
function identifierPart(text) {
  const slug = String(text).toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '');
  return slug || 'threshold';
}

/**
 * Render a value as a Python literal.
 *
 * `JSON.stringify` is not a Python renderer: `true`, `false` and `null` are
 * NameErrors, and a generated test that errors is worse than no test. Returns
 * null when the value cannot be represented, so the caller skips that assertion.
 */
export function pyLiteral(value, depth = 0) {
  if (depth > 4) return null;
  if (value === null) return 'None';
  if (typeof value === 'boolean') return value ? 'True' : 'False';
  if (typeof value === 'number') return Number.isFinite(value) ? String(value) : null;
  if (typeof value === 'string') return JSON.stringify(value);

  if (Array.isArray(value)) {
    const parts = value.map((item) => pyLiteral(item, depth + 1));
    if (parts.some((part) => part === null)) return null;
    return `[${parts.join(', ')}]`;
  }

  if (typeof value === 'object') {
    const parts = [];
    for (const [key, item] of Object.entries(value)) {
      const rendered = pyLiteral(item, depth + 1);
      if (rendered === null) return null;
      parts.push(`${JSON.stringify(key)}: ${rendered}`);
    }
    return `{${parts.join(', ')}}`;
  }

  return null;
}

export function buildPythonBoundaryTest({ importPath, sourceName, cases }) {
  const lines = [];

  lines.push(`"""Boundary tests for ${sourceName}.`);
  lines.push('');
  lines.push('Generated by crucible: the comparison flips its meaning exactly at the');
  lines.push('threshold, and no existing test supplies that case.');
  lines.push('"""');
  lines.push('import os');
  lines.push('import sys');
  lines.push('');
  lines.push('sys.path.insert(0, os.path.abspath(os.path.join(os.path.dirname(__file__), "..")))');
  lines.push('');
  lines.push(`from ${importPath} import ${[...new Set(cases.map((c) => c.fn))].join(', ')}`);
  lines.push('');

  for (const c of cases) {
    lines.push('');
    // `constantName` can be dotted (`limits.MAX`); a dot in a def name is a
    // SyntaxError, so the test name is slugged.
    lines.push(`def test_${c.fn}_at_${identifierPart(c.constantName)}_boundary():`);

    const labels = ['one below', 'exactly at', 'one above'];
    for (let i = 0; i < 3; i += 1) {
      const v = c.observed[i];
      if (v === undefined) continue;

      const input = [c.values.below, c.values.at, c.values.above][i];
      const literal = pyLiteral(v);
      if (literal === null) continue; // not representable in Python; do not lie

      lines.push(`    # ${labels[i]} the threshold (${input})`);
      if (typeof v === 'number') {
        lines.push(`    assert abs(${c.fn}(${input}) - ${v}) < 1e-6`);
      } else {
        lines.push(`    assert ${c.fn}(${input}) == ${literal}`);
      }
    }

    lines.push('');
  }

  return lines.join('\n');
}

/**
 * Emit a Python probe script (not a test) that prints the real values.
 *
 * It must not be named `test_*.py`, or pytest would collect it and fail on the
 * missing test functions.
 */
export function buildPythonProbe({ importPath, cases }) {
  const lines = [];
  lines.push('# generated by crucible — temporary probe, safe to delete');
  lines.push('import json');
  lines.push('import os');
  lines.push('import sys');
  lines.push('');
  lines.push('sys.path.insert(0, os.path.abspath(os.path.join(os.path.dirname(__file__), "..")))');
  lines.push('');
  lines.push(`from ${importPath} import ${[...new Set(cases.map((c) => c.fn))].join(', ')}`);
  lines.push('');
  lines.push('out = []');
  lines.push('def probe(fn, arg):');
  lines.push('    try:');
  lines.push('        out.append({"input": arg, "value": fn(arg)})');
  lines.push('    except Exception as exc:  # noqa: BLE001');
  lines.push('        out.append({"input": arg, "error": str(exc)})');
  lines.push('');

  for (const c of cases) {
    for (const input of [c.values.below, c.values.at, c.values.above]) {
      lines.push(`probe(${c.fn}, ${input})`);
    }
  }

  lines.push('');
  lines.push(`print("CRUCIBLE_PROBE" + json.dumps(out))`);
  return lines.join('\n');
}
